-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.card_sync (
  user_id uuid default auth.uid() not null,
  synced_to bigint default 0 not null,
  repair_from bigint,
  updated_at timestamp with time zone default now() not null,
  constraint card_sync_pkey PRIMARY KEY (user_id),
  constraint card_sync_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint card_sync_check CHECK (((repair_from >= 0) AND (repair_from < synced_to))),
  constraint card_sync_synced_to_check CHECK ((synced_to >= 0))
);

alter table public.card_sync enable row level security;

create policy "read own card sync" on public.card_sync
  as permissive
  for select
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

grant select on table public.card_sync to authenticated;
grant delete, insert, maintain, references, select, trigger, truncate, update on table public.card_sync to service_role;
